def fr_src(rows):
    return '<details class="fr-src"><summary>Sources, with DOIs</summary><ul>'+''.join(f'<li>{row}</li>' for row in rows)+'</ul></details>'
def fr_rr_table(rows, trial_col=False):
    body=''
    for row in rows:
        trial=f'<td data-l="Trials">{row["trials"]}</td>' if trial_col else ''
        note=f'<td data-l="Abstract">{fr_esc(row["sig"])}</td>' if trial_col else ''
        body+='<tr>'+f'<td data-l="Analysis">{fr_esc(row["name"])}</td>'+trial+f'<td data-l="Relative risk">{row["rr"]}</td><td data-l="95 percent interval">{fr_ci(row["ci"])}</td>'+note+'</tr>'
    head='<th>Analysis</th>'+('<th>Trials</th>' if trial_col else '')+'<th>Relative risk</th><th>95 percent interval</th>'+('<th>Abstract</th>' if trial_col else '')
    return '<div class="rtbl-wrap"><table class="rtbl"><thead><tr>'+head+'</tr></thead><tbody>'+body+'</tbody></table></div>'

